import{_ as i,o as a,c as e,a3 as t}from"./chunks/framework.Ctn2UYXF.js";const k=JSON.parse('{"title":"P5 · Changesets 版本计算","description":"","frontmatter":{},"headers":[],"relativePath":"principles/05-changeset-versioning.md","filePath":"principles/05-changeset-versioning.md","lastUpdated":1792494191000}'),n={name:"principles/05-changeset-versioning.md"};function o(l,s,h,p,d,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="p5-·-changesets-版本计算" tabindex="-1">P5 · Changesets 版本计算 <a class="header-anchor" href="#p5-·-changesets-版本计算" aria-label="Permalink to &quot;P5 · Changesets 版本计算&quot;">​</a></h1><blockquote><p><strong>前置</strong>：读完成 <a href="/pnpm-monorepo-tutorial-pages/06-versioning">08 版本发布与 Changesets</a>　|　<strong>配套练习</strong>：<a href="/pnpm-monorepo-tutorial-pages/practice/05-changeset-bump">E5 Changesets 版本 bump</a></p></blockquote><p><code>changeset version</code> 一执行，一堆包的版本号就变了，<code>CHANGELOG.md</code> 也自动写好了。这一章拆开这个「黑盒」：<strong>版本号是怎么从几个 md 文件里算出来的。</strong></p><h2 id="你将学到" tabindex="-1">你将学到 <a class="header-anchor" href="#你将学到" aria-label="Permalink to &quot;你将学到&quot;">​</a></h2><ul><li>changeset 文件的格式与语义</li><li>major / minor / patch 的 bump 规则与「多 changeset 合并」</li><li><code>changeset version</code> 到底做了哪几件事</li><li>依赖范围为什么会被自动改写</li><li><code>fixed</code> 与 <code>linked</code> 两种版本联动策略的差异</li></ul><h2 id="一、changeset-文件长什么样" tabindex="-1">一、changeset 文件长什么样 <a class="header-anchor" href="#一、changeset-文件长什么样" aria-label="Permalink to &quot;一、changeset 文件长什么样&quot;">​</a></h2><p>开发者每完成一个改动，就跑一次 <code>pnpm changeset</code>，生成一个 md 文件（文件名随机，如 <code>.changeset/tame-pandas-jump.md</code>）：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@tutorial/ui&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">minor</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@tutorial/utils&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">patch</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">新增 Card 组件的 loading 态，并修复 utils 的日期格式化边界问题。</span></span></code></pre></div><ul><li>frontmatter 里是<strong>包名 → bump 类型</strong>的映射；</li><li>正文是给人看的变更说明，最终会进入 <code>CHANGELOG.md</code>；</li><li><strong>一个 changeset 可以同时影响多个包</strong>，这是 Monorepo 的关键便利：一次原子改动、一次版本决策。</li></ul><h2 id="二、bump-规则与合并" tabindex="-1">二、bump 规则与合并 <a class="header-anchor" href="#二、bump-规则与合并" aria-label="Permalink to &quot;二、bump 规则与合并&quot;">​</a></h2><p>单包的版本计算遵守语义化版本：</p><table tabindex="0"><thead><tr><th>bump</th><th>版本变化</th><th>语义</th></tr></thead><tbody><tr><td><code>patch</code></td><td>1.2.3 → 1.2.4</td><td>向后兼容的修复</td></tr><tr><td><code>minor</code></td><td>1.2.3 → 1.3.0</td><td>向后兼容的新功能</td></tr><tr><td><code>major</code></td><td>1.2.3 → 2.0.0</td><td>破坏性变更</td></tr></tbody></table><p><strong>多 changeset 合并时取「最高档」</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一包被 patch + minor 命中 → 结果按 minor</span></span>
<span class="line"><span>同一包被 minor + major 命中 → 结果按 major</span></span></code></pre></div><p>这正是「一个人的 patch 不会被另一个人的 major 覆盖掉」的保障。</p><blockquote><p>💡 <strong>0.x 包的特殊性</strong>：<code>0.x</code> 阶段不存在稳定语义，社区通常把破坏性变更记在 <code>minor</code> 上。Changesets 会严格按你写的 bump 类型执行，具体对 <code>0.x</code> 的映射规则请以其官方文档为准——不要凭直觉假设。</p></blockquote><h2 id="三、changeset-version-做了哪几件事" tabindex="-1">三、<code>changeset version</code> 做了哪几件事 <a class="header-anchor" href="#三、changeset-version-做了哪几件事" aria-label="Permalink to &quot;三、\`changeset version\` 做了哪几件事&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 交互式生成 changeset（本地开发时用）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 即 changeset version：应用所有 changeset</span></span></code></pre></div><p><code>changeset version</code> 会<strong>一次性</strong>完成：</p><ol><li>读取 <code>.changeset/</code> 下所有 changeset，按上面的规则合并出每个包的目标版本；</li><li>改写相关 <code>package.json</code> 的 <code>version</code> 字段；</li><li>依据正文生成/追加各包 <code>CHANGELOG.md</code>；</li><li><strong>删除已消费的 changeset 文件</strong>（因此这些文件应提交进 git，而不是 gitignore）；</li><li>视配置联动改写包之间的依赖范围（见下一节）。</li></ol><blockquote><p>⚠️ 第 4 点意味着：<strong>changeset 文件本身是要提交的</strong>。若把它们加进 <code>.gitignore</code>，版本信息就永久丢失了。</p></blockquote><h2 id="四、依赖范围为什么会被自动改写" tabindex="-1">四、依赖范围为什么会被自动改写 <a class="header-anchor" href="#四、依赖范围为什么会被自动改写" aria-label="Permalink to &quot;四、依赖范围为什么会被自动改写&quot;">​</a></h2><p>当 <code>@tutorial/utils</code> 从 <code>1.0.0</code> 升到 <code>1.1.0</code>，而 <code>@tutorial/ui</code> 声明的是 <code>&quot;@tutorial/utils&quot;: &quot;workspace:^&quot;</code>，会发生什么？</p><ul><li><strong>仓库内</strong>：<code>workspace:^</code> 指向本地包，代码上无需任何修改；</li><li><strong>发布时</strong>：按 <a href="/pnpm-monorepo-tutorial-pages/workspace-protocol">第 06 章</a> 的规则改写为 <code>^1.1.0</code>。</li></ul><p>这一切由 <code>.changeset/config.json</code> 的 <code>updateInternalDependencies</code> 控制：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 本仓库 .changeset/config.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;updateInternalDependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;patch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 依赖版本超出范围时，自动给依赖者打 patch</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;baseBranch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;linked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@tutorial/types&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@tutorial/utils&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@tutorial/ui&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;fixed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;access&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;restricted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;commit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong><code>updateInternalDependencies: &quot;patch&quot;</code> 的语义</strong>：某个包的依赖被升级、且<strong>新版本超出了依赖者声明的范围</strong>时，依赖者会自动获得一次 <code>patch</code> bump，并更新其依赖范围。</p><ul><li>设为 <code>patch</code>（默认）：范围失效才联动改动；</li><li>设为 <code>minor</code>：联动改动时用更保守的档位。</li></ul><h2 id="五、fixed-与-linked-两种版本联动" tabindex="-1">五、<code>fixed</code> 与 <code>linked</code>：两种版本联动 <a class="header-anchor" href="#五、fixed-与-linked-两种版本联动" aria-label="Permalink to &quot;五、\`fixed\` 与 \`linked\`：两种版本联动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>规则</th><th>典型场景</th></tr></thead><tbody><tr><td><code>fixed</code></td><td>组内所有包<strong>版本号永远一致</strong>，任一包 bump → 全组一起升到同一版本</td><td>强耦合的套件（如「全家桶」）</td></tr><tr><td><code>linked</code></td><td>组内共享版本<strong>水位</strong>，各自可以是不同版本</td><td>同一技术栈的多包，希望「要么都升、要么都不升」</td></tr></tbody></table><p>本仓库把三个内部包配成了 <code>linked</code>：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;linked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@tutorial/types&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@tutorial/utils&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@tutorial/ui&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span></code></pre></div><p>含义是：这三者<strong>共享水位</strong>——其中任意一个 bump 时，其余包会一起被抬到「组内最高版本」，但各自保留自己的版本号。好处是<strong>避免出现「ui 是 1.3.0、utils 还停在 1.0.0」这种内部版本错位</strong>。</p><blockquote><p>⚠️ 注意 <code>access: &quot;restricted&quot;</code>：本仓库所有包都是 <code>&quot;private&quot;: true</code>，配置为受限发布，<strong>不会被推到公共 npm</strong>。要公开发布需改为 <code>&quot;public&quot;</code>（scoped 包还需付费组织账号）。</p></blockquote><h2 id="六、预发布模式" tabindex="-1">六、预发布模式 <a class="header-anchor" href="#六、预发布模式" aria-label="Permalink to &quot;六、预发布模式&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pre</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> beta</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 进入预发布：版本形如 1.1.0-beta.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 递增预发布号：1.1.0-beta.1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pre</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 退出，回到正式版本线</span></span></code></pre></div><p>预发布期间每次发版只是递增后缀号，不会污染正式版本号——适合「内部灰度 → 正式发布」的节奏。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>忘记跑 <code>pnpm changeset</code></strong> 就直接 <code>changeset version</code> → 没有 changeset，版本不会变（命令会提示）。</li><li><strong>changeset 被 gitignore</strong> → 版本决策丢失，见上文第 4 点。</li><li><strong>在错误的分支上 version</strong> → <code>baseBranch: main</code> 用于判断「相对哪个分支计算」，分支策略乱了会出错。</li><li><strong>以为 <code>workspace:*</code> 会保留 <code>*</code> 到发布</strong> → 不会，见 <a href="/pnpm-monorepo-tutorial-pages/workspace-protocol">第 06 章</a>。</li></ul><h2 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h2><ul><li>[ ] 能写出一个合法的 changeset 文件（含 frontmatter 与正文）</li><li>[ ] 能说出多个 changeset 命中同一包时的合并规则</li><li>[ ] 知道 <code>changeset version</code> 会删除 changeset 文件</li><li>[ ] 能区分 <code>fixed</code> 与 <code>linked</code> 的联动方式</li><li>[ ] 亲手实现版本 bump 计算：<a href="/pnpm-monorepo-tutorial-pages/practice/05-changeset-bump">练习 E5</a></li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>原理篇到此结束。接下来动手：<a href="/pnpm-monorepo-tutorial-pages/practice/">练习篇导读</a></p>`,43)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
